import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"Caddy","description":"Put Caddy in front of the Vite dev server and holodeck, so the test page is served over HTTPS on one origin with the certificate holodeck already has.","frontmatter":{"title":"Caddy","description":"Put Caddy in front of the Vite dev server and holodeck, so the test page is served over HTTPS on one origin with the certificate holodeck already has."},"headers":[],"relativePath":"guides/the-manual/testing/common-setups/caddy.md","filePath":"guides/the-manual/testing/common-setups/caddy.md"}`),a={name:`guides/the-manual/testing/common-setups/caddy.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="caddy" tabindex="-1">Caddy <a class="header-anchor" href="#caddy" aria-label="Permalink to “Caddy”">​</a></h1><p>The <a href="./vite">Vite dev server</a> setup gives the page and the mock server one origin, on plain HTTP. This page adds a reverse proxy in front of both, so the page itself is served over HTTPS with the certificate holodeck&#39;s <code>ensure-cert</code> already issued. Caddy is the worked example. Any reverse proxy that speaks HTTP/2 to its upstream can do the same job.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to “Before you start”">​</a></h2><p>This page assumes the <a href="./vite">Vite dev server</a> setup works, so <code>pnpm test:dev</code> starts holodeck next to Vite and the test helper uses an empty <code>MOCK_HOST</code>. Holodeck serves over TLS only, so a passing suite means <code>ensure-cert</code> already wrote <code>holodeck-localhost.pem</code> and <code>holodeck-localhost-key.pem</code> into your home directory, as <a href="./../server-setup#trust-a-local-certificate">Trust a local certificate</a> describes. The examples use <code>4200</code> for Vite, <code>7358</code> for holodeck, and <code>8443</code> for Caddy.</p><p>Install a <a href="https://caddyserver.com/docs/install" target="_blank" rel="noreferrer">Caddy</a> build that speaks HTTP/2 to its upstreams. Holodeck accepts nothing else, and <a href="#run-it">Run it</a> shows how to confirm it once Caddy is up. Caddy&#39;s reverse proxy quick start is at <a href="https://caddyserver.com/docs/quick-starts/reverse-proxy" target="_blank" rel="noreferrer">https://caddyserver.com/docs/quick-starts/reverse-proxy</a>.</p><h2 id="write-the-caddyfile" tabindex="-1">Write the Caddyfile <a class="header-anchor" href="#write-the-caddyfile" aria-label="Permalink to “Write the Caddyfile”">​</a></h2><p>Save this as <code>Caddyfile</code> in the app&#39;s root, next to <code>testem.js</code>.</p><div class="language-caddyfile"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">caddyfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://localhost:8443 {</span></span>
<span class="line"><span>	tls {$HOME}/holodeck-localhost.pem {$HOME}/holodeck-localhost-key.pem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	@holodeck path /api/* /__record*</span></span>
<span class="line"><span>	handle @holodeck {</span></span>
<span class="line"><span>		reverse_proxy https://localhost:7358</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	handle {</span></span>
<span class="line"><span>		reverse_proxy localhost:4200</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>tls</code> line serves holodeck&#39;s own certificate. Caddy fills in <code>{$HOME}</code> when it reads the file. If <code>ensure-cert</code> wrote the pair somewhere other than your home directory, put those paths here instead. <code>ensure-cert</code> installed its certificate authority with <code>mkcert -install</code>, so the browser already trusts the proxy. Caddy trusts the same authority, so it reaches holodeck without being told to skip certificate checks.</p><p>The <code>@holodeck</code> matcher names the two paths that go straight to holodeck. <code>/api</code> is the <code>namespace</code> from <code>setBuildURLConfig</code>, so if yours differs, change it here. <code>/__record</code> is where each mock helper posts the fixture it records. The last <code>handle</code> sends everything else to Vite, including the requests Vite&#39;s own forwarder would otherwise take, which is why the Vite setup can stay in place underneath.</p><p>The blocks use <code>handle</code> rather than <code>handle_path</code> because <code>handle</code> keeps the <code>/api</code> prefix, and fixture names include it, for example <code>GET::api_users::0</code>.</p><p>A Caddy build that negotiates HTTP/2 needs no transport settings here, and a build that cannot is not fixed by <code>transport http { versions 2 }</code> either.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><ol><li><p>Run <code>pnpm test:dev</code>.</p></li><li><p>In a second terminal, start Caddy from the app&#39;s root. It reads the <code>Caddyfile</code> there and logs <code>server running</code>.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">caddy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div></li><li><p>Confirm that Caddy reached holodeck over HTTP/2. Holodeck answers this probe with a 400, which is fine. The <code>via</code> header is what matters.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://localhost:8443/api/users?__xTestId=probe&amp;__xTestRequestNumber=0&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> via</span></span></code></pre></div><p><code>via: 2.0 Caddy</code> means HTTP/2. <code>via: 1.1 Caddy</code> means this build speaks HTTP/1.1 to the upstream, and the suite will fail with <code>Holodeck failed to record GET api/users (403 )</code>. Install a build that speaks HTTP/2, restart Caddy, and probe again.</p></li><li><p>Open <code>https://localhost:8443/tests</code>.</p></li></ol><p>The suite passes. In the browser&#39;s network panel, every request goes to <code>https://localhost:8443</code>, and there is no <code>OPTIONS</code> request.</p><h2 id="things-to-know" tabindex="-1">Things to know <a class="header-anchor" href="#things-to-know" aria-label="Permalink to “Things to know”">​</a></h2><ul><li>The certificate names only <code>localhost</code>, so keep <code>localhost</code> as the site address. To use another name, such as <code>app.localhost</code>, first issue a certificate with <code>mkcert app.localhost</code>.</li><li>Caddy writes <code>~/.config/caddy/autosave.json</code>. On macOS it also creates <code>~/Library/Application Support/Caddy</code>.</li><li><code>pnpm test</code> is unchanged. Testem never goes through Caddy.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./vite">Vite dev server</a> is the setup this one sits in front of.</li><li><a href="/pr-preview/pr-11205/guides/the-manual/cookbook/holodeck-in-dev-mode">Holodeck in dev mode</a> starts holodeck next to the dev server.</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};